<?php
require __DIR__.'/../../config/database.php';require __DIR__.'/../../config/auth.php';$fid=require_manager_farm($pdo);$uid=$_SESSION['user']['id'];$msg=$err='';$fs=$pdo->prepare("SELECT name,category FROM farms WHERE id=?");$fs->execute([$fid]);$farm=$fs->fetch();
function upload_product_image(){if(empty($_FILES['image']['name']))return null;if($_FILES['image']['error']!==UPLOAD_ERR_OK)throw new Exception('Image upload failed.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['image']['tmp_name']);$ok=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($ok[$mime]))throw new Exception('Use JPG, PNG or WEBP.');$dir=__DIR__.'/../../uploads/products';if(!is_dir($dir))mkdir($dir,0775,true);$n='product_'.time().'_'.bin2hex(random_bytes(4)).'.'.$ok[$mime];move_uploaded_file($_FILES['image']['tmp_name'],$dir.'/'.$n);return 'uploads/products/'.$n;}
if(isset($_POST['add'])){try{$img=upload_product_image();$pdo->prepare("INSERT INTO shop_products(farm_id,name,category,image_path,description,unit,price,stock_qty,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)")->execute([$fid,trim($_POST['name']),trim($_POST['category']),$img,trim($_POST['description']),trim($_POST['unit']),(float)$_POST['price'],(float)$_POST['stock_qty'],$_POST['status'],$uid]);$msg='Product created for '.$farm['name'].'.';}catch(Throwable $e){$err=$e->getMessage();}}
if(isset($_POST['update'])){try{$img=upload_product_image();$q="UPDATE shop_products SET price=?,stock_qty=?,status=?,description=?".($img?",image_path=?":"")." WHERE id=? AND farm_id=?";$a=[(float)$_POST['price'],(float)$_POST['stock_qty'],$_POST['status'],trim($_POST['description'])];if($img)$a[]=$img;$a[]=(int)$_POST['id'];$a[]=$fid;$pdo->prepare($q)->execute($a);$msg='Product updated.';}catch(Throwable $e){$err=$e->getMessage();}}
$q=$pdo->prepare("SELECT * FROM shop_products WHERE farm_id=? ORDER BY category,name");$q->execute([$fid]);$rows=$q->fetchAll();$page_title='Shop Management';require __DIR__.'/../../partials/header.php';?><div class="app-shell"><?php require __DIR__.'/../../partials/manager_sidebar.php';?><main class="app-main"><div class="hero-top"><h2>Shop Management — <?=htmlspecialchars($farm['name'])?></h2><p class="mb-0">Only products belonging to your assigned farm are shown and editable.</p></div><?php if($msg):?><div class="alert alert-success mt-3"><?=$msg?></div><?php endif;?><?php if($err):?><div class="alert alert-danger mt-3"><?=htmlspecialchars($err)?></div><?php endif;?><div class="cardx p-4 mt-3"><h5>Add Farm Product</h5><form method="post" enctype="multipart/form-data" class="row g-3"><input type="hidden" name="add" value="1"><div class="col-md-3"><label>Name</label><input class="form-control" name="name" required></div><div class="col-md-2"><label>Category</label><input class="form-control" name="category" value="<?=htmlspecialchars($farm['category'])?>" required></div><div class="col-md-2"><label>Unit</label><input class="form-control" name="unit" placeholder="Litre/KG/Piece" required></div><div class="col-md-2"><label>Price</label><input class="form-control" type="number" step=".01" name="price" required></div><div class="col-md-2"><label>Opening Stock</label><input class="form-control" type="number" step=".01" name="stock_qty" value="0"></div><div class="col-md-4"><label>Photo</label><input class="form-control" type="file" name="image" accept="image/*"></div><div class="col-md-5"><label>Description</label><input class="form-control" name="description"></div><div class="col-md-2"><label>Status</label><select class="form-select" name="status"><option>active</option><option>draft</option><option>hidden</option></select></div><div class="col-12"><button class="btn btn-success">Create Product</button></div></form></div><div class="row g-3 mt-1"><?php foreach($rows as $r):?><div class="col-lg-6"><div class="cardx p-3"><b><?=htmlspecialchars($r['name'])?></b><div class="text-muted"><?=$r['stock_qty']?> <?=$r['unit']?> · <?=htmlspecialchars($r['category'])?></div><form method="post" enctype="multipart/form-data" class="row g-2 mt-2"><input type="hidden" name="update" value="1"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="col-3"><input class="form-control" type="number" step=".01" name="price" value="<?=$r['price']?>"></div><div class="col-3"><input class="form-control" type="number" step=".01" name="stock_qty" value="<?=$r['stock_qty']?>"></div><div class="col-3"><select class="form-select" name="status"><option <?=$r['status']==='active'?'selected':''?>>active</option><option <?=$r['status']==='draft'?'selected':''?>>draft</option><option <?=$r['status']==='hidden'?'selected':''?>>hidden</option></select></div><div class="col-3"><input class="form-control" type="file" name="image"></div><div class="col-9"><input class="form-control" name="description" value="<?=htmlspecialchars($r['description']??'')?>"></div><div class="col-3"><button class="btn btn-success w-100">Save</button></div></form></div></div><?php endforeach;?></div></main></div>